ALTER TABLE Empresa ADD COLUMN ownerId VARCHAR(191) NOT NULL DEFAULT 'professor', DROP INDEX Empresa_cnpj_key, ADD UNIQUE INDEX Empresa_ownerId_cnpj_key(ownerId, cnpj);
ALTER TABLE Cargo ADD COLUMN ownerId VARCHAR(191) NOT NULL DEFAULT 'professor', DROP INDEX Cargo_codigo_key, ADD UNIQUE INDEX Cargo_ownerId_codigo_key(ownerId, codigo);
ALTER TABLE Funcionario ADD COLUMN ownerId VARCHAR(191) NOT NULL DEFAULT 'professor', DROP INDEX Funcionario_codigo_key, DROP INDEX Funcionario_cpf_key, ADD UNIQUE INDEX Funcionario_ownerId_codigo_key(ownerId, codigo), ADD UNIQUE INDEX Funcionario_ownerId_cpf_key(ownerId, cpf);
CREATE TABLE Professor (id VARCHAR(191) NOT NULL, nome VARCHAR(191) NOT NULL, email VARCHAR(191) NOT NULL, senhaHash VARCHAR(191) NOT NULL, PRIMARY KEY(id), UNIQUE INDEX Professor_email_key(email)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE Sessao (tokenHash VARCHAR(191) NOT NULL, userId VARCHAR(191) NOT NULL, role VARCHAR(191) NOT NULL, expiresAt DATETIME(3) NOT NULL, PRIMARY KEY(tokenHash)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE Trabalho (id VARCHAR(191) NOT NULL, alunoId VARCHAR(191) NOT NULL, tipo VARCHAR(191) NOT NULL, dados JSON NOT NULL, createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY(id), INDEX Trabalho_alunoId_idx(alunoId)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
